WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (504::BIGINT, 'Es un curso fácil, no son las clases más interesantes del mundo, pero la profe es buena nota, sus quices no son muy complejos y hay notas que básicamente regala. Sin embargo, no es tan suave calificando y se fija en los detalles. Con el material que da es suficiente, no hacen tanta falta las clases'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'cad482cfb3fd851db7dab5312683382bf093a75b4a2c44bfa3a38c6674f56e00'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe es un bostezo, parece que esta muert@ en vida, tal vez no explica tan mal pero lo aburrida que hace la clase complica poner atencion, lo bueno es que sube todos los apuntes de la clase en el tec digital, hace quices MUY duros, no la recomiendo porq al final de cuentas hay q ser autodidacta'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '3605a9b819e541febe597086a574981b72293219095f8bc03dfc71f37fab05f5'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'No es una mala profesora y explica ok. Y hasta ahí, las clases son un bostezo increíble y terminé viendo clases de otro profesor para entender la materia que en si no es difícil. Los quices son DUROS no entiendo pq los hace asi .'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '78731b29d3cae099da7a787f3b9c835f291590074ecdc14657d1e5ba17c466a2'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Es buena persona, pero no la recomiendo como profesora, explica de manera innecesariemente complicada cosas que son muy simples y no fomenta la participacion en clase, ir a clase es como ir a un funeral, nadie habla. Sumado a lo anterior, el primer examen califica de manera muy brusca.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2026-01-12T00:00:00+00:00'::TIMESTAMPTZ, '748718cdeff086260915cd1b005e1760916dabd528e4404b54ae1d3dc8aeff06'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'De que explica bien, sí lo hace. Las presentaciones y apuntes prometen. Eso sí, califica muy duro, los quices son rudos y su tono de voz me daba sueño. Pero dentro de lo que cabe, explica bien y se nota que le gusta.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, '124bce77a40afd2cfa1a7c410281f32bf3bbed2026891050574e315d127838cc'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'En general la profesora explica bien, aunque busca abarcarlos y darlos por visto, antes que el estudiante entienda, se siente que va a la carrera. Los quices que hace no son fáciles, más que ayudar al estudiante parece que busca perjudicarlo en ese rubro. Califica duro en todas la evualuaciones.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-12-18T00:00:00+00:00'::TIMESTAMPTZ, '92a18fc53e553c2d96357d81301b4aec27513404fcc0d9442445743927ed893f'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Explica increíble, hace siempre todo en el iPad y lo sube al tecDigital si a uno no le da tiempo de copiar. Los quizzes sí son bastante difíciles, agarra ejercicios de exámenes incluso extraordinarios para el quiz. Deja tareas. Califica un poco duro, difícil sacarse 100. Recomendada 50/50'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '530c95255b64a30aafa6a531703cb53469814434aa76f4a765057aa33118c156'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Califica justo, puede y a veces no se le entiende muy bien porque puede ir un poco rápido pero fuera de eso es muy buena profesora, un poco seria pero siempre es muy abierta en consultas y no tiene problema en explicar de nuevo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'c5a345f0e4f5b7d2f5495dfbbad06e2e0f3710c714a0dda086f01ead114c9c98'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Increíble profesora, explica súper claro, deja pocas tareas, aclara dudas súper bien. Una profesora demasiado increíble y admirable, demasiado recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-14T00:00:00+00:00'::TIMESTAMPTZ, '35a02ea665e3f7ed3453460a6c52371f0b0fb43e3067ab1ccacc7cc93c3441ba'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'El comentario de abajo es un poco fake, ella desde el primer dia de clases menciona que da tiempo para escribir, por lo que uno le puede decir si que le de un minuto para terminar de escribir, eso es cosa de la comunicacion.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-14T00:00:00+00:00'::TIMESTAMPTZ, '605bcf30b864fffe9057339914c24ead81f2beaa397cc8f398a2be29ccce4407'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'No matriculen con ella para nada, no se dejen guiar por lo que dice acá, yo lo hice y fue lo peor. En clase hace las cosas con el ipad y no da tiempo para que uno copie los ejercicios entonces uno no sabe nada y también califica mega mega duro. No da pero no medio punto. No la recomiendo para nada'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'aa5c725c7dce3722b40ee80c42a7cffa611835487a13174b3ff8870b09989ee7'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Es buena profe pero aveces no explica muy bien y hace el tema un poco enredado, los quices aveces son muy complicados más de lo que se vio en clase'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'a39d2054862dd424e22ac9b4d11f3cfc5c7c2fcbda2fd5347160777958820661'::TEXT, ARRAY[2444]::BIGINT[]),
    (504::BIGINT, 'Yo llevé un grupo RN con ella. De las mejores profes de mate que he visto. Es muy ordenada con su cronograma, ayuda mucho y explica muy bien. Es muy buena opción tanto para u curso por primera vez o para repitentes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c4344c6587da85ffb3f3eaa64785e1c117ab8ce11987820d05c4c9dc274e7d46'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Muy buena profe, pero deja muchisimos trabajos que valen demasiado poco para el tiempo que demanda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '2f5e59356f2c493c4580afb90cc02cfb849b04e07fe40e8953dd62f606695524'::TEXT, ARRAY[563]::BIGINT[]),
    (504::BIGINT, 'Una profe con la que vale la pena matricular. Para todas las clases hacía un pdf muy completo con ejercicios, definiciones, teoremas los cuales servían mucho para las evaluaciones. Es muy ordenada y siempre está dispuesta a resolver dudas. A veces nos ponía ejercicios en clase para ganar pts extra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '40f830198039b39451f6d090e000a8da7abc81675a1ecc10c24d2e689986926a'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'LA MEJOR PROFE, quiere que uno entienda y ayuda dentro y fuera de clase. 20/10.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ac798c7b14256f3b1649a2380aee5863abbf973521649d7d7feb5f1034ae2e08'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profesora!! Explica muy claro, las clases son completas y sirven de enorme preparación para los examenes. Siempre está pendiente y atenta a las dudas y las atiende de la mejor manera. Tiene un don para enseñar y motivar a los estudiantes!! Se aprende bastante con ella!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3245925099ea55bd23322038d55bb8c6e1a3d3e30004eacf754c0e547ea8266b'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe explica muy bien. Realmente se dedica a aclarar dudas pero sí es muy rigurosa con su horario de trabajo. Además, aunque deja muchas tareas, ayudan a compensar la nota del curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a39c9673bd07446691f9a68b28d3acae115b6b4df88e004db3a62e9bd7dcaba1'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profesora, super ordenada con todos trabajos y apegada al horario. Despues de cada clase nos enviaba la materia. Explica y hace bastantes ejercicios, y recibe dudas con todo gusto. Pocas tareas y muy faciles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '8415c2b5c75f65afd8009ddc9bcdf16b777394d78011a3ea3cd6dd44cdcbdc15'::TEXT, ARRAY[1018]::BIGINT[]),
    (504::BIGINT, 'Explica muy rápido, pero con volver a ver la clase se entiende super bien. Da muchos ejemplos y deja super clara la materia. Deja bastantes evaluaciones, pero son fáciles. El primer parcial es el más difícil, los demás temas son fáciles. Matricule con ella siempre que pueda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-10T00:00:00+00:00'::TIMESTAMPTZ, '8be89765d4c8f37f7c17e7bf16c4fd7e7a263f2f8233a72d0210f0443281bc06'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profesora, no duden en matricular con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'b9dda241ba0b36a9cd3bf7f0c5c558989f62046fd596f663afe08f0c5267fa9e'::TEXT, ARRAY[563]::BIGINT[]),
    (504::BIGINT, 'Explica bien y deja todo claro. Prefiere que se vean la clase sincrónica, incluso aveces deja ejercicios de puntos extra para el final de la clase y no graba esa parte. Probablemente es la mejor para el curso'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, '2661d07f30d095dc3b63f279a5fa6c19943150105feaf36fce44653e15fa9702'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Explica muy claro, y el material que utiliza en la clase es muy útil para los examenes y quices. Deja resumenes semanales de la materia y otros trabajos que ayudan a repasar la materia. También es la coordinadora, entonces está pendiente de las fechas importantes de las evaluaciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Da crédito extra']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a42e800a56d785f21713be110a35f4e8123355361f84a4d5af19aab73bb33a57'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe explica muy bien, pero sus clases se vuelven muy aburridas y largas. Deja muchos trabajos: actividades grupales, tareas, portafolios semanales y se apega mucho a las reglas. Es un poco cortante y seria pero si se le pide ayuda explica muy bien y entiende problemas personales.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b48d162eb20cd2eb0d304d1f0b8259d7f05b7e9b576847a3da245f80df4eb43e'::TEXT, ARRAY[564]::BIGINT[]),
    (504::BIGINT, 'De las mejores profes de la escuela de mate. Explica muy claro los temas y es súper ordenada con la materia y se basa en el material que brinda la cátedra. Es un poco cortante, pero es una profe que ayuda si uno le pregunta algo. Además la forma en que evalúa el % de quizes/ tareas ayuda muchisimo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '08dc3de1ef9af46008c424dbac1d526cdb3dc1aa94980c6f57518c0c251531ad'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Una excelente opción, hace muchos ejercicios de práctica, y es bastante clara, aunque a veces es poco flexible vale la pena. Eso sí, también hay que apoyarse en el material de la cátedra, ya que ella se basa en eso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-17T00:00:00+00:00'::TIMESTAMPTZ, '1ea458adafc20ee984fb027931affa0223a466ed42d42f3785871c20e8dbe464'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe explica bien. Aunque las clases son aburridas y a veces va demasiado rápido.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'b26eaa22358b161c5e42d4b3b0e9eb7473af08c73a26f0c908569f51d03bad6e'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Muy buena profe, ayuda bastante que ella es la coordinadora del curso, entonces todo lo tiene muy claro con respecto a fechas, trabajos etc. No sé para el resto de Cálculos, pero para CAL es la mejor opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6a518f31dad52cfd12d748c15be49343f0490d10a6806031b891b81526345361'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe es demasiado buena explicando, hace bastante ejemplos y también va de la mano de la teoría. Las clases son entretenidas y la profe califica justo, mantiene el tecdigital actualizado que es importante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '40d48f38e8790935eb20aff817b2e941090fb086d7839b00848be3efc2b6271a'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profe. Hace muchos ejemplos y explica muy claro. Usa buenas aplicasiones para explicar bien en la virtualidad. Cada semana hay que hacer un resumen pero ayuda demasiado para los parciales. Siempre está atenta a dudas. La mejor de Algebra Lineal'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'bb3aa5f679d698d1c202d8503c88e9babbb9add519101d1183f57268072fb68b'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Es la mejor profe de mate que he tenido, se le entiende súper bien. Lo único malo son las clases largas, pero vale demasiado la pena llevarla con ella.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '31df6d4cac53b24cb66b9fe78ab6f9cb4007f4e41be4f8a60a76c69ac058b37e'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'La profe es super ordenada, prepara un pdf con los ejercicios que va a hacer en clase. Ayuda bastante si usted le pregunta! Solo que en la modalidad virtual a veces va muy rápido.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3d4347bd4a56ae1d60425b1ace30a8398ad6b435de8a2ffa71661f3ef5c75738'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'De las mejores profesoras de todo el TEC, da clases excelentes, nada más es de llevar al día lo de la cátedra y el curso se pasa solo. Además ofrece bastantes facilidades para pasar el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'cf938b0fc027c5a4252a17735fac3755ca30c6394d739e75cf12d1d48e73bf0b'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Esta profesora es genial me sorprende la nota tan baja que tiene, es muy buena para explicar y da bastantes ejemplos que se pueden aplicar en exámenes, la teoría que a veces es necesaria ya que la da muy claramente, las clases son un poco largas pero muy explicitas. RECOMENDADA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '63fe37d8b4f61275bff1154d0bac817e37fbce113078a71fd8c6f17e41106ff6'::TEXT, ARRAY[605]::BIGINT[]),
    (504::BIGINT, 'Explica muy claramente, pero si no se repasa un poco al menos le puede ir mal. Es muy justa con la asistencia y los reclamos, no duden en matricular con ella.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7340930828ba3a6c2ea0c88b57b1a6d0c601704dc40e92d6a73bfdac82e611d'::TEXT, ARRAY[605]::BIGINT[]),
