    (504::BIGINT, 'Sin duda de las mejores profesoras que he tenido. Deja material para poder repasar y responde a cualquier duda que tengan los estudiantes. Siempre prepara las clases y eso ayuda a que no se pierda tiempo en la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '01038aed66284ba3959b12d578c90d58f443dd3f8f651bcc633cb2769fc88fb7'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Muy recomenda. Explica muy bien. Deja el material de la clase que resulta muy útil a la hora de estudiar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'a50c18901739bb4a2887437cffb6f9d592151e1b7dcb995261e4cd7bf115ab4a'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Es una profesora que se adaptó de la mejor manera a la modalidad virtual. Explica super bien la materia, no tiene problema en aclarar dudas y se nota que sabe un montón. Los quices son más dificiles que el examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '13d3e35fcdb6e5b0e9a94be2244e6092c10cc3fb57652be254017d9caa811ed7'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'De las mejores profes que he tenido en el TEC. Se preocupó mucho porque aprendieramos y explica demasiado bien, justo lo necesario. Los materiales que hace en las clases tienen toda la teoria y es super ordenada. SUPER recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '2b72fe865286779cd6e9ac1389272e3187af2d173dacd5f9cc020f94cf9e1cf4'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profesora, mantiene contacto con los estudiantes en todo momento. Atiende todas las dudas que uno tenga. Explica genial.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '069e2ec57f6fb3b65191c3fb82f3c2b88348bc45bcce1321ff750cc65a7ed9b4'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Súper ordenada. Los quices son iguales al examen. A veces tiene errores pequeños en la solución de los ejercicios pero eso no afecta el hecho de que explica muy bien en sí la materia del curso. Lo que más rescato es que responde las dudas en cuanto pueda sin importar la hora o día. Es buena opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'e6119662ae4f9edf8b8caf645d0f8b9376de6c5f9590259b5e9ff5c2e99b50af'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Excelente profe, se preocupa porque sus estudiantes aprendan y resuelve dudas o problemas con el curso siempre, en telegram, correo, clase, como sea siempre responde. Recomendada 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '4c14555e280cc528bc3331c20ff3bc28fa12994e44dda9feb08da1457c9c5d42'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Súper buena profe se adaptó muy bien a la modalidad virtual, deja quices muy parecidos a lo que sale en el exámen. Explica muy bien y es muy ordenada con los docuementos y videos sobre la clase. Sin embargo practicar es muy importante como todo curso. Matricule con ella sin miedo. 100% recomendada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '1a3fc8951dfdc2f5c72463419795613d1a1e7076c1f346689d172b335c3a7cea'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Muy buena profesora, se preocupa que el estudiante entienda y aclara todas las dudas. No obstante, la práctica de ejercicios es fundamental para un buen desempeño en el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'e157137634ffdf5b72947d17825e1aba855376feb3257118221b9001cd21b0fb'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Muy buena profesora 100% recomendada, muy clara y ordenada, ya sea en notas o con sus clases por lo que los exámenes son fáciles si se repasa la materia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'b316f9ce62a45001708aa2259880730eb4a1bb87e7efde2cb7f343f3d4b91c27'::TEXT, ARRAY[564]::BIGINT[]),
    (504::BIGINT, 'Una profesora excelente, es muy clara y explica bastante bien. Super ordenada con el Tec Digital, las grabaciones de las clases y los documentos de la clase. Las clases son de 2h o un poco más a veces, sin embargo, no deja nada por fuera. De las mejores profesoras!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'b7e794c082e4055e58a4b519fb349a6920b6b2ee518308d9f18740bc08d9cdb5'::TEXT, ARRAY[634]::BIGINT[]),
    (504::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'b0ad89742836d77fb2c06b237cab30700207dec9065f5a20dae670530a72aa3a'::TEXT, ARRAY[564]::BIGINT[]),
