    (504::BIGINT, 'Excelente profesora, muy ordenada al resolver ejercicios, resuelve ejercicios de muy buen nivel que lo preparan bien a uno para el examen, en fin, puede matricular sin miedo con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'f9f869c1bd198c2f193f172a30162f09e9138029447ccc6d52ea014e137d371f'::TEXT, ARRAY[634]::BIGINT[]),
