    (504::BIGINT, 'Califica relativamente suave. Es muy ordenada para explicar y sabe la materia a la perfección. Resuelve las dudas que sean necesarias para que usted entienda. Elimina quices bajos. 100% recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'adf99e834b5f25aca994b087a8e0c00478bb6e3978db78f191cd90791506b8a1'::TEXT, ARRAY[923]::BIGINT[]),
